@staticmethod
def _candidate_fingerprint(blocks_raw: list) -> str:
    """Stable SHA-256 content fingerprint of a candidate's raw block list.

    Mirrors ``LedgerService._candidate_fingerprint`` so recovery can check
    the persisted record against the re-parsed candidate without importing
    the service layer. Key order and whitespace are normalized.
    """
    return hashlib.sha256(
        json.dumps(blocks_raw, sort_keys=True, ensure_ascii=False).encode("utf-8")
    ).hexdigest()

@staticmethod
def _validate_transaction(path: str, tx: Transaction) -> None:
    """Recompute a transaction's id and check its Ed25519 signature."""
    if (
        not isinstance(tx.sender, str)
        or not isinstance(tx.recipient, str)
        or not tx.sender
        or not tx.recipient
    ):
        raise StateRecoveryError(path, "transaction has invalid from/to fields")
    if (
        isinstance(tx.amount, bool)
        or not isinstance(tx.amount, int)
        or tx.amount <= 0
    ):
        raise StateRecoveryError(
            path, f"transaction {getattr(tx, 'sender', '?')} has non-positive amount"
        )
    if not isinstance(tx.signature, str) or not tx.signature:
        raise StateRecoveryError(path, "transaction is missing a signature")
    if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
        raise StateRecoveryError(
            path, f"transaction {tx.tx_id} has an invalid signature"
        )

@staticmethod
def create_genesis() -> Block:
    # The genesis block is born confirmed.
    return Block.create(
        height=0,
        prev_hash=GENESIS_PREV_HASH,
        transactions=[],
        status=STATUS_CONFIRMED,
    )

def _compute_derived(self) -> tuple[dict[str, int], dict[str, dict]]:
    """Build the confirmed-only transaction index and account activity.

    Pending blocks are excluded: only confirmed blocks contribute to
    balances and to the tx_id -> height index. Pure: it returns fresh
    dicts and never mutates store state, so callers can compute a
    prospective view and publish it only after a successful write.
    """
    tx_index: dict[str, int] = {}
    accounts: dict[str, dict] = {}
    for block in self.chain:
        if block.status != STATUS_CONFIRMED:
            continue
        for tx in block.transactions:
            tx_index[tx.tx_id] = block.height
            for account in (tx.sender, tx.recipient):
                entry = accounts.setdefault(
                    account, {"sent": 0, "received": 0, "transactions": []}
                )
                entry["transactions"].append(tx.tx_id)
            accounts[tx.sender]["sent"] += tx.amount
            accounts[tx.recipient]["received"] += tx.amount
    return tx_index, accounts

def rebuild_derived(self) -> None:
    """Rebuild the confirmed-only transaction index and account activity.

    Pending blocks are excluded: only confirmed blocks contribute to
    balances and to the tx_id -> height index.
    """
    self.tx_index, self.accounts = self._compute_derived()

def save(self) -> None:
    """Atomically persist chain, state, pending set, index and accounts.

    The new state is first written to a uniquely named ``.ledger-*``
    snapshot in the same directory and force-fsynced; only after that does
    an atomic ``os.replace`` promote it to the main file. A crash between
    the fsync and the promotion leaves the snapshot behind, where the
    startup scan finds it as a recovery candidate. The in-memory
    ``generation`` is advanced only after the promotion succeeds, so every
    *successful* atomic write corresponds to exactly one generation.
    """
    # Compute the prospective confirmed-only views WITHOUT publishing them:
    # they describe the *post-write* chain and must not become visible in
    # memory until the promotion succeeds. A failure anywhere below leaves
    # ``self.tx_index``/``self.accounts`` describing the last durably
    # committed chain, which is exactly the state the caller's own rollback
    # restores the rest of the fields to.
    next_index, next_accounts = self._compute_derived()
    next_generation = self.generation + 1
    # The in-memory log, its hash head and checkpoint always move together:
    # refuse to persist a document where they disagree, since that could
    # never recover. Callers append through append_audit_event(), which
    # advances both atomically.
    if self.audit_checkpoint != audit.make_checkpoint(self.audit_events):
        raise RuntimeError(
            "audit_checkpoint does not match the audit log head; refusing "
            "to persist an inconsistent snapshot"
        )
    # The current signer must agree with the newest retained history entry
    # and its seed must derive its public key, so a persisted document
    # never carries an internally inconsistent checkpoint key.
    audit_signer_state = None
    if self.audit_signer is not None:
        derived = crypto.derive_public_key(self.audit_signer["private_key"])
        latest = self.audit_signer_history[-1]
        if (
            derived != self.audit_signer["public_key"]
            or self.audit_signer["version"] != latest["version"]
            or self.audit_signer["public_key"] != latest["public_key"]

        (self.store.tip_hash(), self.store.chain)
    ]
    contenders.extend(self.store.forks.items())
    contenders.sort(key=lambda item: (-len(item[1]), item[0]))
    return contenders[0]

def submit_fork_candidate(self, payload: object) -> tuple[int, dict]:
    """POST /v1/forks/candidates — validate and store a candidate fork.

    Returns 201 with the fork descriptor S. Malformed or invalid forks
    return 400; a fork already known (identical to the canonical tip or an
    existing candidate tip) returns 409.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    blocks_raw = payload.get("blocks")
    if not isinstance(blocks_raw, list):
        return 400, {"error": "missing field: blocks (must be a list)"}
    try:
        fork = self.store.validate_fork_blocks(blocks_raw)
    except ValueError as exc:
        return 400, {"error": str(exc)}
    summary = self._fork_summary(fork)
    # An exported fork (the five-field {tip_hash, height, length, status,
    # blocks} document) may be resubmitted verbatim; every supplied summary
    # field is re-verified against the recomputed descriptor.
    for field in ("tip_hash", "height", "length", "status"):
        if field in payload and payload[field] != summary[field]:
            return 400, {"error": f"summary field {field!r} does not match the blocks"}
    tip_hash = fork[-1].block_hash
    with self.store.lock:
        self._prune_expired_syncs()
        # A tip hash equal to any canonical block hash means the candidate
        # is exactly the canonical chain or a prefix of it (the block hash
        # binds height, parent and Merkle root), so it carries nothing new.
        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
        self.store.forks[tip_hash] = fork
        try:
            self.store.save()
        except BaseException:
            self.store.forks.pop(tip_hash, None)
            raise
    return 201, self._fork_summary(fork)

def get_chain(self) -> tuple[int, dict]:
    """GET /v1/chain — canonical chain, candidates sorted by tip hash and
    the adoptable winner (a non-canonical chain that beats canonical).
    """
    with self.store.lock:
        self._prune_expired_syncs()
        canonical = self._fork_summary(self.store.chain)
        candidates = [
            self._fork_summary(self.store.forks[tip])
            for tip in sorted(self.store.forks)
        ]
        winner_tip, winner_chain = self._winning_fork()
        adoptable: list[dict] = []
        if winner_tip != self.store.tip_hash():
            adoptable.append(self._fork_summary(winner_chain))
        return 200, {
            "canonical": canonical,
            "candidates": candidates,
            "adoptable": adoptable,
        }

def adopt_fork(self, tip_hash: object) -> tuple[int, dict]:
    """POST /v1/forks/{tip_hash}/adopt — atomically switch to the winner.

    Unknown tips return 404; adopting anything other than the current
    winning (longest / smallest-tip-hash) chain returns 409. Adoption
    replaces the canonical chain and mempool in one atomic write that
    advances the generation and rebuilds all indexes; transactions unique
    to the old chain's confirmed history return to the mempool, while
    pending-block transactions never enter it.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        self._prune_expired_syncs()
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        winner_tip, _ = self._winning_fork()
        if winner_tip != tip_hash:
            return 409, {"error": "only the winning fork can be adopted"}
        old_chain = self.store.chain
        old_pending = dict(self.store.pending)
        self.store.forks.pop(tip_hash)
        self.store.replace_chain(fork)
        # An adopted synced tip keeps its sync records (queryable until
        # expiry); record the adoption once per provenance entry. The
        # adopted tip summary is frozen from the adopted fork itself and
        # is never rewritten by later expiry.
        adopted_summary = self._fork_summary(fork)
        adopted_keys = sorted(
            key
            for key, rec in self.store.syncs.items()
            if rec["tip_hash"] == tip_hash
        )
        for rec_source, request_id in adopted_keys:
            self.store.append_audit_event(
                EVENT_SYNC_ADOPTED,
                {
                    "source": rec_source,
                    "request_id": request_id,
                    "tip_hash": tip_hash,
                    "expires_at": self.store.syncs[
                        (rec_source, request_id)
                    ]["expires_at"],
                    "height": adopted_summary["height"],
                    "length": adopted_summary["length"],
                    "status": adopted_summary["status"],
                },
            )
        try:
            self.store.save()
        except BaseException:
            # Restore the pre-adoption in-memory state on a failed write.
            self.store.chain = old_chain
            self.store.pending = old_pending
            self.store.forks[tip_hash] = fork
            self.store.rebuild_derived()
            self.store.truncate_audit_events(len(adopted_keys))
            raise
        return 200, self._fork_summary(fork)

def export_fork(self, tip_hash: object) -> tuple[int, dict]:
    """GET /v1/forks/{tip_hash}/export — full export of a candidate fork.

    Only stored candidates are exportable: the canonical tip, an unknown
    tip and a malformed tip hash (not 64 lowercase hex chars) all return
    404. The response carries exactly five fields — the fork descriptor
    (tip_hash, height, length, status, all describing the tip block) plus
    the full block list including the genesis block, every transaction's
    signature and an optional pending tip — and can be resubmitted to
    POST /v1/forks/candidates verbatim.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        body = self._fork_summary(fork)
        body["blocks"] = [block.to_dict() for block in fork]
        return 200, body

